		expected bool
	}{
		{
			name:     "no patterns",
			path:     "file.txt",
			patterns: nil,
			expected: false,
		},
		{
			name:     "matching extension",
			path:     "file.tmp",
			patterns: []string{"*.tmp"},
			expected: true,
		},
		{
			name:     "non-matching extension",
			path:     "file.txt",
			patterns: []string{"*.tmp"},
			expected: false,
		},
		{
			name:     "matching directory",
			path:     ".git/config",
			patterns: []string{".git"},
			expected: true,
		},
		{
			name:     "multiple patterns - first matches",
			path:     "file.tmp",
			patterns: []string{"*.tmp", "*.bak", ".git"},
			expected: true,
		},
		{
			name:     "multiple patterns - last matches",
			path:     ".git/objects/abc",
			patterns: []string{"*.tmp", "*.bak", ".git"},
			expected: true,
		},
		{
			name:     "multiple patterns - none match",
			path:     "src/main.go",
			patterns: []string{"*.tmp", "*.bak", ".git"},
			expected: false,
		},
		{
			name:     "nested path with matching component",
			path:     "src/.git/config",
			patterns: []string{".git"},
			expected: true,
		},
		{
			name:     "exact filename match",
			path:     "Dockerfile",
			patterns: []string{"Dockerfile"},
			expected: true,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			result := shouldExclude(tt.path, tt.patterns)
			if result != tt.expected {
				t.Errorf("shouldExclude(%q, %v) = %v, want %v",
