// Close closes SFTP, SSH, and bastion connections.
// Close is idempotent - calling it multiple times is safe.
// Returns an error if any close operation fails. Multiple errors are aggregated.
func (c *Client) Close() error {
	var errs []error

	if c.sftpClient != nil {
		if err := c.sftpClient.Close(); err != nil {
			errs = append(errs, fmt.Errorf("failed to close SFTP client: %w", err))
		}
		c.sftpClient = nil
	}
	if c.sshClient != nil {
		if err := c.sshClient.Close(); err != nil {
			errs = append(errs, fmt.Errorf("failed to close SSH client: %w", err))
		}
		c.sshClient = nil
	}
	if c.bastionClient != nil {
		if err := c.bastionClient.Close(); err != nil {
			errs = append(errs, fmt.Errorf("failed to close bastion client: %w", err))
		}
		c.bastionClient = nil
	}

	if len(errs) > 0 {
		return fmt.Errorf("errors closing client: %w", errors.Join(errs...))
	}
	return nil
}

// IsHealthy checks if the client's SSH connection is still valid.
func (c *Client) IsHealthy() bool {
	return c != nil && c.sshClient != nil && c.sftpClient != nil
}

// UploadFile uploads a local file to the remote host.
func (c *Client) UploadFile(ctx context.Context, localPath, remotePath string) error {
	if err := ctx.Err(); err != nil {
		return fmt.Errorf("operation cancelled: %w", err)
	}

	localFile, err := os.Open(localPath)
	if err != nil {
		return fmt.Errorf("failed to open local file: %w", err)
	}
	defer localFile.Close()

	remoteDir := filepath.Dir(remotePath)
	if remoteDir != "" && remoteDir != "/" && remoteDir != "." {
		if err := c.sftpClient.MkdirAll(remoteDir); err != nil {
			return fmt.Errorf("failed to create remote directory %s: %w", remoteDir, err)
		}
	}

	remoteFile, err := c.sftpClient.Create(remotePath)
	if err != nil {
		return fmt.Errorf("failed to create remote file: %w", err)
	}
	defer remoteFile.Close()

	done := make(chan error, 1)
	go func() {
		_, err := io.Copy(remoteFile, localFile)
		if err != nil {
			done <- fmt.Errorf("failed to copy file content: %w", err)
			return
		}
		done <- nil
	}()

	select {
	case <-ctx.Done():
		return fmt.Errorf("upload cancelled: %w", ctx.Err())
	case err := <-done:
		return err
	}
}

// GetFileHash returns the SHA256 hash of a remote file.
func (c *Client) GetFileHash(ctx context.Context, remotePath string) (string, error) {
	if err := ctx.Err(); err != nil {
		return "", fmt.Errorf("operation cancelled: %w", err)
	}

	file, err := c.sftpClient.Open(remotePath)
	if err != nil {
		return "", fmt.Errorf("failed to open remote file: %w", err)
	}
	defer file.Close()

	h := sha256.New()
	done := make(chan error, 1)
	go func() {
		_, err := io.Copy(h, file)
		done <- err
	}()

	select {
	case <-ctx.Done():
		return "", fmt.Errorf("hash computation cancelled: %w", ctx.Err())
	case err := <-done:
		if err != nil {
			return "", fmt.Errorf("failed to read remote file: %w", err)
		}
		return "sha256:" + hex.EncodeToString(h.Sum(nil)), nil
	}
}

