				Optional:            true,
				Computed:            true,
				Default:             stringdefault.StaticString("root"),
				Validators: []validator.String{
					UnixOwner(),
				},
			},
			"group": schema.StringAttribute{
				MarkdownDescription: "File group on remote. Defaults to the SSH user's primary group.",
				Optional:            true,
