			// Optional - sync options.
			"exclude": schema.ListAttribute{
				MarkdownDescription: "List of glob patterns to exclude from sync (e.g., `*.tmp`, `.git`, `.DS_Store`). Supports standard glob syntax with `*` and `?` wildcards.",
				Optional:            true,
