// TestValidateOwnerGroup tests owner/group validation.
func TestValidateOwnerGroup(t *testing.T) {
	tests := []struct {
		name        string
		value       string
		fieldName   string
		expectError bool
	}{
		{
			name:        "empty is valid",
			value:       "",
			fieldName:   "owner",
			expectError: false,
		},
		{
			name:        "simple username",
			value:       "root",
			fieldName:   "owner",
			expectError: false,
		},
		{
			name:        "username with underscore",
			value:       "www_data",
			fieldName:   "owner",
			expectError: false,
		},
		{
			name:        "username with dash",
			value:       "some-user",
			fieldName:   "owner",
			expectError: false,
		},
		{
			name:        "numeric id",
			value:       "1000",
			fieldName:   "owner",
			expectError: false,
		},
		{
			name:        "starts with letter",
			value:       "user123",
			fieldName:   "owner",
			expectError: false,
		},
		{
			name:        "starts with underscore",
			value:       "_user",
			fieldName:   "owner",
			expectError: false,
		},
		{
			name:        "injection attempt with semicolon",
			value:       "root;rm -rf /",
			fieldName:   "owner",
			expectError: true,
		},
		{
			name:        "injection attempt with dollar",
			value:       "root$(whoami)",
			fieldName:   "owner",
			expectError: true,
		},
		{
			name:        "injection attempt with backtick",
			value:       "root`id`",
			fieldName:   "owner",
			expectError: true,
		},
		{
			name:        "injection attempt with pipe",
			value:       "root|whoami",
			fieldName:   "owner",
			expectError: true,
		},
		{
			name:        "injection attempt with ampersand",
			value:       "root&whoami",
			fieldName:   "owner",
			expectError: true,
		},
		{
			name:        "name too long",
			value:       "this_is_a_very_long_username_that_exceeds_thirty_two_characters",
			fieldName:   "owner",
			expectError: true,
		},
		{
			name:        "starts with dash",
			value:       "-invalid",
			fieldName:   "owner",
			expectError: true,
		},
		{
			name:        "starts with digit",
			value:       "9user",
			fieldName:   "owner",
			expectError: true,
		},
		{
			name:        "contains space",
			value:       "user name",
			fieldName:   "owner",
			expectError: true,
		},
		{
			name:        "contains slash",
			value:       "user/name",
			fieldName:   "owner",
			expectError: true,
		},
		{
			name:        "contains backslash",
			value:       "user\\name",
			fieldName:   "owner",
			expectError: true,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			err := validateOwnerGroup(tt.value, tt.fieldName)
			if tt.expectError {
				if err == nil {
					t.Errorf("expected error for value %q, got nil", tt.value)
				}
			} else {
				if err != nil {
					t.Errorf("unexpected error for value %q: %v", tt.value, err)
				}
			}
		})
	}
}

