   136→
   137→// connectToBastionWithDeps connects to a bastion host using the given dependencies.
   138→func connectToBastionWithDeps(config Config, timeout time.Duration, deps *Dependencies) (*ssh.Client, error) {
   139→	var authMethods []ssh.AuthMethod
   140→
   141→	if config.BastionPassword != "" {
   142→		authMethods = append(authMethods, ssh.Password(config.BastionPassword))
   143→	} else {
   144→		var keyData []byte
   145→		var err error
   146→
