   287→// buildCertificateAuthWithDeps builds certificate auth using the given dependencies.
   288→func buildCertificateAuthWithDeps(config Config, deps *Dependencies) (ssh.AuthMethod, error) {
   289→	var keyData []byte
   290→	var err error
   291→
   292→	if config.PrivateKey != "" {
   293→		keyData = []byte(config.PrivateKey)
   294→	} else if config.KeyPath != "" {
   295→		keyData, err = deps.FileReader(ExpandPath(config.KeyPath))
   296→		if err != nil {
   297→			return nil, fmt.Errorf("failed to read private key file: %w", err)
   298→		}
   299→	} else {
   300→		return nil, fmt.Errorf("certificate auth requires private key (set private_key or key_path)")
   301→	}
   302→
   303→	signer, err := ssh.ParsePrivateKey(keyData)
   304→	if err != nil {
   305→		return nil, fmt.Errorf("failed to parse private key: %w", err)
   306→	}
   307→
   308→	var certData []byte
   309→	if config.Certificate != "" {
   310→		certData = []byte(config.Certificate)
   311→	} else if config.CertificatePath != "" {
   312→		certData, err = deps.FileReader(ExpandPath(config.CertificatePath))
   313→		if err != nil {
   314→			return nil, fmt.Errorf("failed to read certificate file: %w", err)
   315→		}
   316→	} else {
   317→		return nil, fmt.Errorf("certificate auth requires certificate (set certificate or certificate_path)")
   318→	}
   319→
   320→	pubKey, _, _, _, err := ssh.ParseAuthorizedKey(certData)
   321→	if err != nil {
   322→		return nil, fmt.Errorf("failed to parse certificate: %w", err)
   323→	}
   324→
   325→	cert, ok := pubKey.(*ssh.Certificate)
   326→	if !ok {
   327→		return nil, fmt.Errorf("provided file is not an SSH certificate")
   328→	}
   329→
   330→	certSigner, err := ssh.NewCertSigner(cert, signer)
   331→	if err != nil {
   332→		return nil, fmt.Errorf("failed to create certificate signer: %w", err)
   333→	}
