			remotePath:   "/opt/my stacks/app/docker-compose.yaml",
			cmdResult:    CommandResult{Stdout: "", Stderr: "", Err: nil},
			wantErr:      false,
			wantDirPart:  "cd '/opt/my stacks/app'",
			wantFilePart: "-f 'docker-compose.yaml'",
		},
